create table if not exists public.deployment_migration_history(migration text primary key,checksum text,applied_at timestamptz not null default now(),applied_by text not null default'controlled-release');
create table if not exists public.deployment_releases(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,environment text not null check(environment in('development','staging','production')),version text not null,build_id text not null,commit_sha text not null,deployed_at timestamptz not null default now(),status text not null check(status in('started','healthy','degraded','failed')),metadata jsonb not null default'{}');
alter table public.deployment_migration_history enable row level security;alter table public.deployment_releases enable row level security;
create policy "deployment migration administrators read"on public.deployment_migration_history for select to authenticated using(exists(select 1 from public.workspace_members wm join public.roles r on r.id=wm.role_id where wm.user_id=auth.uid()and wm.status='active'and r.code in('organization_owner','organization_admin'))or(auth.jwt()->'app_metadata'->>'role')='super_admin');
create policy "deployment releases administrators read"on public.deployment_releases for select to authenticated using((public.current_workspace_role(workspace_id)in('organization_owner','organization_admin')and organization_id=(select wm.organization_id from public.workspace_members wm where wm.workspace_id=deployment_releases.workspace_id and wm.user_id=auth.uid()and wm.status='active'limit 1))or(auth.jwt()->'app_metadata'->>'role')='super_admin');
insert into public.deployment_migration_history(migration,checksum)values('20260828000000_sprint64_production_deployment_platform','managed-by-supabase-cli')on conflict(migration)do nothing;
revoke all on public.deployment_migration_history,public.deployment_releases from anon;grant select on public.deployment_migration_history,public.deployment_releases to authenticated;
